ur DMA physical buffer. // This is used with any buffer that was mapped into our physical // buffer. PVOID VirtualToPhysAddress (PVOID pvVirtual) { // Make sure that the given virtual address is within the range of // our buffer. ASSERT (((PUCHAR)pvVirtual >= (PUCHAR)g_pvDmaVirtualBase) && ((PUCHAR)pvVirtual < ((PUCHAR)g_pvDmaVirtualBase + NSCIRDA_DMA_BUFFER_LEN))); // Physical address is the base physical address plus the offset // in the virtual address space. return (PVOID) ((DWORD)NSCIRDA_DMA_BUFFER_BASE_PA + (DWORD)pvVirtual - (DWORD)g_pvDmaVirtualBase); } const int DmaAddrReg[4] = { 0x00, 0x02, 0x04, 0x06}; const int DmaCountReg[4] = { 0x01, 0x03, 0x05, 0x07}; const int DmaPageReg[4] = { 0x87, 0x83, 0x81, 0x82}; // Define the DMA-mode register structure. typedef struct _DMA_MODE { UCHAR Channel : 2; UCHAR TransferType : 2; UCHAR AutoInitialize : 1; UCHAR AddressDecrement : 1; UCHAR RequestMode : 2; }DMA_MODE, *PDMA_MODE; // Define TransferType values. #define VERIFY_TRANSFER 0x00 #define READ_TRANSFER 0x01 // Read from the device. #define WRITE_TRANSFER 0x02 // Write to the device. // Define RequestMode values. #define DEMAND_REQUEST_MODE 0x00 #define SINGLE_REQUEST_MODE 0x01 #define BLOCK_REQUEST_MODE 0x02 #define CASCADE_REQUEST_MODE 0x03 #define DMA_SETMASK 4 #define DMA_CLEARMASK 0 #define DMA_READ 4 #define DMA_WRITE 8 #define DMA_SINGLE_TRANSFER 0x40 #define DMA_AUTO_INIT 0x10 // Auto initialization mode // Define DMA 1 address and count structure (for 8237 compatibility) typedef struct _DMA1_ADDRESS_COUNT { UCHAR DmaBaseAddress; UCHAR DmaBaseCount; } DMA1_ADDRESS_COUNT, *PDMA1_ADDRESS_COUNT; // Define DMA 1 control register structure (for 8237 compatibility) typedef struct _DMA1_CONTROL { DMA1_ADDRESS_COUNT DmaAddressCount[4]; UCHAR DmaStatus; UCHAR DmaRequest; UCHAR SingleMask; UCHAR Mode; UCHAR ClearBytePointer; UCHAR MasterClear; UCHAR ClearMask; UCHAR AllMask; } DMA1_CONTROL, *PDMA1_CONTROL; NDIS_DMA_DESCRIPTION g_DMA_Description; BOOL g_fRegistered; UINT g_nDmaChannel; /*********************************************************************/ NDIS_STATUS NdisMRegisterDmaChannel ( PNDIS_HANDLE phMiniportDmaHandle, NDIS_HANDLE hMiniportAdapterHandle, UINT nDmaChannel, BOOLEAN fDma32BitAddresses, PNDIS_DMA_DESCRIPTION pDmaDescription, ULONG ulMaximumLength) { NDIS_STATUS Status = NDIS_STATUS_SUCCESS; DEBUGMSG (ZONE_INIT | ZONE_DMA, (TEXT("+NdisMRegisterDmaChannel (%#x, %#x, %d, %d, %#x, %d
