 bMode = bReadWrite | g_nDmaChannel; WRITE_PORT_UCHAR ((PUCHAR) 0x0B, bMode); // LO byte address of buffer. WRITE_PORT_UCHAR ((PUCHAR)DMAAddr, (UCHAR) (Offset2 & 0xFF)); // HI byte address of buffer. WRITE_PORT_UCHAR ((PUCHAR)DMAAddr, (UCHAR) (Offset2 >> 8)); // Physical page number. WRITE_PORT_UCHAR ((PUCHAR)DMAPage, (UCHAR) Page); // LO byte of count. WRITE_PORT_UCHAR ((PUCHAR)DMACount, (UCHAR) ((Length - 1) & 0xFF)); // HI byte of count. WRITE_PORT_UCHAR ((PUCHAR)DMACount, (UCHAR) ((Length - 1) >> 8)); DBGDMA((TEXT("ReadCount (before) = %d"), NdisMReadDmaCounter (phMiniportDmaHandle))); // Done programming the DMA, enable it. WRITE_PORT_UCHAR ((PUCHAR) 0x0A, (UCHAR) DMAChanOffset); done: DBGDMA((TEXT("-NdisMSetupDmaTransfer [%s]"), DBG_NDIS_RESULT_STR (*pStatus))); return; } /*********************************************************************/ VOID NdisMCompleteDmaTransfer ( PNDIS_STATUS Status, PNDIS_HANDLE MiniportDmaHandle, PNDIS_BUFFER Buffer, ULONG Offset, ULONG Length, BOOLEAN WriteToDevice) { DBGDMA((TEXT("+NdisMCompleteDmaTransfer %s: buf = 0x%x, offset = %d, len = %d"), (WriteToDevice == TRUE) ? TEXT("TX") : TEXT("RX"), Buffer, Offset, Length)); // Disable the DMA. WRITE_PORT_UCHAR ((PUCHAR) 0x0A, (UCHAR) (g_nDmaChannel | 4)); DBGDMA((TEXT("-NdisMCompleteDmaTransfer [NDIS_STATUS_SUCCESS]"))); *Status = NDIS_STATUS_SUCCESS; } /*********************************************************************/ ULONG NdisMReadDmaCounter (NDIS_HANDLE MiniportDmaHandle) { UCHAR bLo, bHi; bLo = READ_PORT_UCHAR ((PUCHAR) DmaCountReg[g_nDmaChannel]); bHi = READ_PORT_UCHAR ((PUCHAR) DmaCountReg[g_nDmaChannel]); DBGDMA((TEXT("NdisMReadDmaCounter [StatusReg = 0x%x, Count = %d]"), READ_PORT_UCHAR ((PUCHAR) 0x08), bHi << 8 | bLo)); return (bHi << 8 | bLo); }
